// Only app routes generated by the authorized server inbox are navigable.
export function safeNotificationLink(value){
  return typeof value==='string'&&!/[\u0000-\u0020\\]/.test(value)&&/^\/(leave|lnd|performance|benefits|onboarding|solvers|solver-assessment-applications|employees\/[^/?#]+|forms|policies|my-tasks)(?:[?#].*)?$/.test(value)?value:null;
}

export async function readAndOpenNotification(item,{markRead,navigate}){
  const link=safeNotificationLink(item.link);
  if(link)navigate(link);
  if(!item.is_read)await markRead(item.id);
  return Boolean(link);
}
